/* ==========================================
   CORETAX - REORDER KOLOM PAJAK KELUARAN
   Asumsi: 2 kolom kontrol + 18 kolom data
   ========================================== */

/* Atur baris tabel menjadi CSS Grid */
table thead tr,
table tbody tr {
    display: grid !important;
    grid-template-columns:
        32px
        52px
        180px
        160px
        115px
        160px
        120px
        100px
        75px
        120px
        145px
        135px
        120px
        100px
        150px
        150px
        110px
        130px
        150px
        170px !important;
    width: max-content !important;
    min-width: 100% !important;
}

/* Seluruh sel tabel */
table thead tr > *,
table tbody tr > * {
    min-width: 0 !important;
    box-sizing: border-box !important;
}

/* Kolom kontrol kiri: jangan dipindahkan */
table thead tr > :nth-child(-n+2),
table tbody tr > :nth-child(-n+2) {
    order: 0 !important;
}

/* Urutan kolom baru
   Posisi selector = urutan kolom asli + 2 kolom kontrol */

/* 1. Referensi (asli 15) */
table thead tr > :nth-child(17),
table tbody tr > :nth-child(17) { order: 1 !important; }

/* 2. Nama Pembeli (asli 2) */
table thead tr > :nth-child(4),
table tbody tr > :nth-child(4) { order: 2 !important; }

/* 3. NPWP Pembeli (asli 1) */
table thead tr > :nth-child(3),
table tbody tr > :nth-child(3) { order: 3 !important; }

/* 4. Tanggal Faktur Pajak (asli 5) */
table thead tr > :nth-child(7),
table tbody tr > :nth-child(7) { order: 4 !important; }

/* 5. Nomor Faktur Pajak (asli 4) */
table thead tr > :nth-child(6),
table tbody tr > :nth-child(6) { order: 5 !important; }

/* 6. Masa Pajak (asli 6) */
table thead tr > :nth-child(8),
table tbody tr > :nth-child(8) { order: 6 !important; }

/* 7. Tahun (asli 7) */
table thead tr > :nth-child(9),
table tbody tr > :nth-child(9) { order: 7 !important; }

/* 8. Harga Jual/DPP (asli 10) */
table thead tr > :nth-child(12),
table tbody tr > :nth-child(12) { order: 8 !important; }

/* 9. DPP Nilai Lain (asli 11) */
table thead tr > :nth-child(13),
table tbody tr > :nth-child(13) { order: 9 !important; }

/* 10. PPN (asli 12) */
table thead tr > :nth-child(14),
table tbody tr > :nth-child(14) { order: 10 !important; }

/* 11. PPNBM (asli 13) */
table thead tr > :nth-child(15),
table tbody tr > :nth-child(15) { order: 11 !important; }

/* 12. Kode Transaksi (asli 3) */
table thead tr > :nth-child(5),
table tbody tr > :nth-child(5) { order: 12 !important; }

/* 13. Status Faktur (asli 8) */
table thead tr > :nth-child(10),
table tbody tr > :nth-child(10) { order: 13 !important; }

/* 14. ESign Status (asli 9) */
table thead tr > :nth-child(11),
table tbody tr > :nth-child(11) { order: 14 !important; }

/* 15. Penandatangan (asli 14) */
table thead tr > :nth-child(16),
table tbody tr > :nth-child(16) { order: 15 !important; }

/* 16. Metode Input (asli 16) */
table thead tr > :nth-child(18),
table tbody tr > :nth-child(18) { order: 16 !important; }

/* 17. Dilaporkan oleh Penjual (asli 17) */
table thead tr > :nth-child(19),
table tbody tr > :nth-child(19) { order: 17 !important; }

/* 18. Dilaporkan oleh Pemungut PPN (asli 18) */
table thead tr > :nth-child(20),
table tbody tr > :nth-child(20) { order: 18 !important; }
